import net.neoforged.neoforge.gametest.*;
import static dev.cosmerearcanists.copper.CopperNetwork.*;
@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class CopperGameTests {
    private static FakePlayer player(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"Archivist"));p.setGameMode(GameType.SURVIVAL);p.setPos(Vec3.atCenterOf(h.absolutePos(new BlockPos(1,20,1))));PowerAttributes.set(p,"f:copper",1);return p;}
    private static ItemStack mind(FakePlayer p){var s=new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.fromNamespaceAndPath(CosmereArcanists.MOD_ID,"copper_metalmind_ring")));p.setItemInHand(InteractionHand.OFF_HAND,s);return s;}
    private static void request(FakePlayer p,int op,UUID entry,String title,String text,int number,byte[] bytes){var session=CopperService.session(p);CopperService.request(p,new Request(op,session.token,entry,title,text,number,bytes));}
    private static List<CopperPage> pages(FakePlayer p){return new ArrayList<>(CopperBooks.get(p.server).books.get(CopperService.session(p).book).values());}
    private static byte[] png(int w,int h)throws IOException{var image=new java.awt.image.BufferedImage(w,h,java.awt.image.BufferedImage.TYPE_INT_RGB);image.setRGB(0,0,0xA0B0C0);var output=new ByteArrayOutputStream();ImageIO.write(image,"png",output);return output.toByteArray();}
    @GameTest(template="empty") public static void copperNotebookStoresNotesLocationsAndSurvivesSavedDataRoundTrip(GameTestHelper h){
        var p=player(h);var item=mind(p);PowerData.state(p,"f:copper",-1);var session=CopperService.open(p,false);h.assertTrue(session!=null&&Metalminds.bound(item),"Writing binds the physical singleton notebook");
        request(p,SAVE,ZERO,"Mining notes","Tin below the river.\nReturn with torches.",0,new byte[0]);request(p,LOCATION,ZERO,"River mine","Entrance under the bridge",0,new byte[0]);var rows=pages(p);h.assertTrue(rows.size()==2&&rows.get(0).text().contains("\n")&&rows.get(1).position().equals(p.blockPosition())&&rows.get(1).dimension().equals(p.level().dimension().location().toString()),"Notes preserve lines and waypoints use server-recorded position/dimension");
        var saved=CopperBooks.get(p.server).save(new CompoundTag(),h.getLevel().registryAccess());var loaded=CopperBooks.load(saved,h.getLevel().registryAccess());h.assertTrue(new ArrayList<>(loaded.books.get(session.book).values()).equals(rows),"World SavedData reload preserves memory pages");h.assertTrue(CopperService.identity(item.copy()).equals(session.book),"Physical item serialization/copies retain notebook identity");CopperService.clear(p);h.succeed();
    }
    @GameTest(template="empty") public static void copperReadingIsPrivateAndStaleSessionsCannotEdit(GameTestHelper h){
        var p=player(h);var item=mind(p);PowerData.state(p,"f:copper",-1);var old=CopperService.open(p,false);request(p,SAVE,ZERO,"Private","Keep this",0,new byte[0]);PowerData.state(p,"f:copper",1);CopperService.open(p,false);request(p,SAVE,ZERO,"Forgery","Not accepted",0,new byte[0]);h.assertTrue(pages(p).size()==1,"Tapping is read only");
        PowerData.state(p,"f:copper",-1);CopperService.open(p,false);CopperService.request(p,new Request(SAVE,old.token,ZERO,"Stale","Not accepted",0,new byte[0]));h.assertTrue(pages(p).size()==1,"Old menu token cannot edit a newer session");
        var other=player(h);other.setItemInHand(InteractionHand.OFF_HAND,item);PowerData.state(other,"f:copper",1);h.assertTrue(CopperService.open(other,false)==null,"Foreign player cannot read owned memories");p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);CopperService.tick(p);h.assertTrue(CopperService.session(p)==null,"Lost contact revokes the menu immediately");CopperService.clear(p);CopperService.clear(other);h.succeed();
    }
    @GameTest(template="empty") public static void copperScreenshotChunksPersistOnServerAndReloadWithoutClientFiles(GameTestHelper h)throws Exception{
        var p=player(h);mind(p);PowerData.state(p,"f:copper",-1);var session=CopperService.open(p,false);byte[] bytes=png(16,8);UUID transfer=UUID.randomUUID();request(p,BEGIN,transfer,"River view","Looking east",bytes.length,new byte[0]);int mid=bytes.length/2;request(p,CHUNK,transfer,"","",0,Arrays.copyOfRange(bytes,0,mid));request(p,CHUNK,transfer,"","",mid,Arrays.copyOfRange(bytes,mid,bytes.length));request(p,FINISH,transfer,"","",0,new byte[0]);var page=pages(p).getFirst();h.assertTrue(page.kind()==CopperPage.SCREENSHOT,"Only a completed valid upload creates an image page");byte[] stored=CopperImages.read(p.server,page.id());var decoded=ImageIO.read(new ByteArrayInputStream(stored));h.assertTrue(decoded.getWidth()==16&&decoded.getHeight()==8&&(decoded.getRGB(0,0)&0xFFFFFF)==0xA0B0C0,"Server PNG survives independent decode with original pixel data");
        var saved=CopperBooks.get(p.server).save(new CompoundTag(),h.getLevel().registryAccess());var reload=CopperBooks.load(saved,h.getLevel().registryAccess());h.assertTrue(reload.books.get(session.book).get(page.id()).equals(page)&&CopperImages.read(p.server,page.id()).length>0,"Saved notebook reload still references its server-side screenshot");request(p,DELETE,page.id(),"","",0,new byte[0]);h.assertTrue(pages(p).isEmpty()&&!java.nio.file.Files.exists(CopperImages.directory(p.server).resolve(page.id()+".png")),"Deletion removes page and associated server image");CopperService.clear(p);h.succeed();
    }
    @GameTest(template="empty") public static void copperRejectsMalformedOversizedAndOutOfOrderScreenshots(GameTestHelper h)throws Exception{
        boolean rejected=false;try{CopperImages.normalize(png(513,1));}catch(IOException expected){rejected=true;}h.assertTrue(rejected,"Image dimensions are checked before decoding");rejected=false;try{CopperImages.normalize(new byte[16]);}catch(IOException expected){rejected=true;}h.assertTrue(rejected,"Invalid image bytes are rejected");
        var p=player(h);mind(p);PowerData.state(p,"f:copper",-1);CopperService.open(p,false);var id=UUID.randomUUID();var bytes=png(4,4);request(p,BEGIN,id,"Incomplete","",bytes.length,new byte[0]);request(p,CHUNK,id,"","",1,bytes);request(p,FINISH,id,"","",0,new byte[0]);h.assertTrue(pages(p).isEmpty(),"Out-of-order uploads never create screenshot entries");
        rejected=false;try{new Request(CHUNK,ZERO,ZERO,"","",0,new byte[CopperImages.CHUNK+1]);}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Oversized chunks cannot enter a request");rejected=false;try{new Image(ZERO,ZERO,10,Integer.MAX_VALUE,new byte[16]);}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Image offsets cannot overflow the transfer bound");CopperService.clear(p);h.succeed();
    }
    @GameTest(template="empty") public static void copperLimitsAndConfigurationPreserveExistingMemories(GameTestHelper h){
        var p=player(h);mind(p);PowerData.state(p,"f:copper",-1);CopperService.open(p,false);int max=FeruchemyConfig.COPPER_PAGES.get();boolean enabled=FeruchemyConfig.COPPER.get();try{FeruchemyConfig.COPPER_PAGES.set(1);request(p,SAVE,ZERO,"First","Saved",0,new byte[0]);request(p,SAVE,ZERO,"Second","Not saved",0,new byte[0]);h.assertTrue(pages(p).size()==1,"Configured page limit cannot be exceeded");UUID book=CopperService.session(p).book;FeruchemyConfig.COPPER.set(false);CopperService.tick(p);h.assertTrue(CopperService.session(p)==null&&CopperBooks.get(p.server).books.get(book).size()==1,"Disabling revokes access while preserving world memories");h.assertTrue(PowerAttributes.strength(p,"f:copper")==1,"Configuration never removes the power");}finally{FeruchemyConfig.COPPER_PAGES.set(max);FeruchemyConfig.COPPER.set(enabled);CopperService.clear(p);}h.succeed();
    }
    @GameTest(template="empty") public static void copperPacketsRoundTripAndStackedItemsCannotBecomeNotebooks(GameTestHelper h){
        var p=player(h);var item=mind(p);item.setCount(2);PowerData.state(p,"f:copper",-1);h.assertTrue(CopperService.open(p,false)==null&&!Metalminds.bound(item),"Stacked copper cannot become a memory-bearing singleton");
        var page=new CopperPage(UUID.randomUUID(),CopperPage.WAYPOINT,"Home","Remember the portal","minecraft:overworld",new BlockPos(12,70,-4));var snapshot=new Snapshot(true,UUID.randomUUID(),UUID.randomUUID(),"Copper ring",false,List.of(page),"",123,1024,614400);var b=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{Snapshot.CODEC.encode(b,snapshot);h.assertTrue(Snapshot.CODEC.decode(b).equals(snapshot),"Notebook metadata codec preserves coordinates and notes");}finally{b.release();}CopperService.clear(p);h.succeed();
    }
    @GameTest(template="empty") public static void drainingCopperErasesAllMemoriesAndServerScreenshots(GameTestHelper h)throws Exception{
        var p=player(h);var item=mind(p);PowerData.state(p,"f:copper",-1);var session=CopperService.open(p,false);UUID book=session.book;
        request(p,SAVE,ZERO,"Secret notes","Erase this text",0,new byte[0]);request(p,LOCATION,ZERO,"Secret place","Erase this location",0,new byte[0]);byte[] bytes=png(8,4);var transfer=UUID.randomUUID();request(p,BEGIN,transfer,"Secret screenshot","Erase these pixels",bytes.length,new byte[0]);request(p,CHUNK,transfer,"","",0,bytes);request(p,FINISH,transfer,"","",0,new byte[0]);var image=pages(p).stream().filter(row->row.kind()==CopperPage.SCREENSHOT).findFirst().orElseThrow();request(p,IMAGE,image.id(),"","",0,new byte[0]);
        double drained=Metalminds.transfer(item,p.getUUID(),"copper",-Metalminds.charge(item));h.assertTrue(drained<0&&!Metalminds.bound(item)&&CopperService.identity(item).equals(ZERO),"Full drain removes charge, ownership and notebook identity");h.assertTrue(!CopperBooks.get(p.server).books.containsKey(book)&&CopperService.session(p)==null,"Full drain removes notes, locations and open/download session");h.assertTrue(!java.nio.file.Files.exists(CopperImages.directory(p.server).resolve(image.id()+".png")),"Full drain deletes the server-side PNG");
        var reloaded=CopperBooks.load(CopperBooks.get(p.server).save(new CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(!reloaded.books.containsKey(book),"Erased memories are absent from saved/reloaded metadata");CopperService.open(p,false);h.assertTrue(!CopperService.session(p).book.equals(book)&&pages(p).isEmpty(),"Reusing an emptied piece creates a new blank notebook");CopperService.clear(p);h.succeed();
    }
    @GameTest(template="empty") public static void copperWipeWorksWhenDisabledAndCopiesCannotResurrectIt(GameTestHelper h){
        var p=player(h);var item=mind(p);PowerData.state(p,"f:copper",-1);UUID book=CopperService.open(p,false).book;request(p,SAVE,ZERO,"Private","Gone on wipe",0,new byte[0]);var copy=item.copy();p.setItemInHand(InteractionHand.MAIN_HAND,copy);double capacity=Metalminds.capacity(item);boolean enabled=FeruchemyConfig.COPPER.get();
        try{FeruchemyConfig.COPPER.set(false);h.assertTrue(Metalminds.wipe(item),"Explicit wipe handles a bound notebook");h.assertTrue(!CopperBooks.get(p.server).books.containsKey(book)&&CopperService.identity(item).equals(ZERO)&&Metalminds.owner(item)==null,"Wiping while disabled removes all memory identity and metadata");h.assertTrue(Metalminds.capacity(item)==capacity,"Wiping preserves physical metalmind capacity");FeruchemyConfig.COPPER.set(true);PowerData.state(p,"f:copper",1);h.assertTrue(CopperService.open(p,false)==null&&!Metalminds.bound(copy)&&CopperService.identity(copy).equals(ZERO),"A stale copied identity cannot reopen or resurrect wiped memories");}
        finally{FeruchemyConfig.COPPER.set(enabled);CopperService.clear(p);}h.succeed();
    }
    @GameTest(template="empty") public static void copperDeletionFailuresPersistAndRetryWithoutRestoringAccess(GameTestHelper h)throws Exception{
        var p=player(h);var item=mind(p);PowerData.state(p,"f:copper",-1);UUID book=CopperService.open(p,false).book;UUID image=UUID.randomUUID();var data=CopperBooks.get(p.server);data.books.get(book).put(image,new CopperPage(image,CopperPage.SCREENSHOT,"Fault fixture","","minecraft:overworld",BlockPos.ZERO));var path=CopperImages.directory(p.server).resolve(image+".png");java.nio.file.Files.createDirectories(path);var obstruction=path.resolve("filesystem-fault");java.nio.file.Files.writeString(obstruction,"test");
        try{Metalminds.wipe(item);h.assertTrue(!data.books.containsKey(book)&&data.erasedImages.contains(image),"Filesystem failure cannot retain access; failed PNG deletion remains queued");var reload=CopperBooks.load(data.save(new CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(reload.erasedImages.contains(image)&&!reload.books.containsKey(book),"Cleanup obligation and erasure survive SavedData reload");java.nio.file.Files.delete(obstruction);CopperService.retryErasedImages(p.server,64);h.assertTrue(!data.erasedImages.contains(image)&&!java.nio.file.Files.exists(path),"Retry deletes the remaining server data once storage works");}
        finally{java.nio.file.Files.deleteIfExists(obstruction);java.nio.file.Files.deleteIfExists(path);data.erasedImages.remove(image);CopperService.clear(p);}h.succeed();
    }
    @GameTest(template="empty") public static void copperPartialDrainPreservesMemoriesButLegacyEmptyCleanupErasesThem(GameTestHelper h){
        var p=player(h);var item=mind(p);PowerData.state(p,"f:copper",-1);UUID book=CopperService.open(p,false).book;request(p,SAVE,ZERO,"Memory","Preserve until empty",0,new byte[0]);Metalminds.transfer(item,p.getUUID(),"copper",-.5);h.assertTrue(CopperBooks.get(p.server).books.containsKey(book)&&CopperService.identity(item).equals(book),"Partial drain does not erase a still-charged notebook");var root=item.get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag();var tag=root.getCompound("cosmerearcanists_metalmind");tag.putDouble("charge",0);root.put("cosmerearcanists_metalmind",tag);item.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(root));Metalminds.unkeyEmpty(item);h.assertTrue(!CopperBooks.get(p.server).books.containsKey(book)&&CopperService.identity(item).equals(ZERO),"Legacy empty bindings purge their stale server memories");CopperService.clear(p);h.succeed();
    }

    @GameTest(template="empty") public static void copperDataCapacityStoresProportionalChargeAndRejectsOverflow(GameTestHelper h){
        var p=player(h);var item=mind(p);PowerData.state(p,"f:copper",-1);var session=CopperService.open(p,false);
        String text="x".repeat(2048);request(p,SAVE,ZERO,"Long note",text,0,new byte[0]);
        long used=CopperService.usedBytes(p,session);h.assertTrue(used==64+9+2048&&CopperService.capacityBytes(item)>=used&&Metalminds.charge(item)>1,"Saving text stores the proportional charge instead of a fixed one-charge flag");
        double charge=Metalminds.charge(item);request(p,DELETE,pages(p).getFirst().id(),"","",0,new byte[0]);h.assertTrue(CopperService.usedBytes(p,session)==0&&Metalminds.charge(item)==charge,"Deleting data frees space without discarding charge");
        // Restrict this fixture to one charge of physical capacity; a larger UTF-8 note cannot fit.
        var root=item.get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag();var tag=root.getCompound("cosmerearcanists_metalmind");tag.putDouble("capacity",1);tag.putDouble("charge",1);root.put("cosmerearcanists_metalmind",tag);item.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(root));
        request(p,SAVE,ZERO,"Too large",text,0,new byte[0]);h.assertTrue(pages(p).isEmpty()&&Metalminds.charge(item)==1,"Rejected writes change neither pages nor charge");
        request(p,SAVE,ZERO,"Small","Fits",0,new byte[0]);h.assertTrue(pages(p).size()==1,"Smaller memories still fit after a rejected write");CopperService.clear(p);h.succeed();
    }
    @GameTest(template="empty") public static void copperPartialDrainRetainsReadsAndAllowsShrinkingOrRefilling(GameTestHelper h){
        var p=player(h);var item=mind(p);PowerData.state(p,"f:copper",-1);var session=CopperService.open(p,false);request(p,SAVE,ZERO,"Note","a".repeat(1000),0,new byte[0]);UUID page=pages(p).getFirst().id();
        Metalminds.transfer(item,p.getUUID(),"copper",.1-Metalminds.charge(item));h.assertTrue(CopperService.usedBytes(p,session)>CopperService.capacityBytes(item),"A partial drain can leave preserved memories over budget");
        PowerData.state(p,"f:copper",1);h.assertTrue(CopperService.open(p,false)!=null&&pages(p).getFirst().text().length()==1000,"Over-budget memories remain readable");
        PowerData.state(p,"f:copper",-1);CopperService.open(p,false);request(p,SAVE,page,"Note","b".repeat(500),0,new byte[0]);h.assertTrue(pages(p).getFirst().text().length()==500&&Math.abs(Metalminds.charge(item)-.1)<1e-8,"Shrinking existing data requires no additional charge");
        request(p,SAVE,page,"Note","c".repeat(1500),0,new byte[0]);h.assertTrue(pages(p).getFirst().text().length()==1500&&CopperService.capacityBytes(item)>=CopperService.usedBytes(p,CopperService.session(p)),"Growing data refills only its required charge");
        Metalminds.transfer(item,p.getUUID(),"copper",-Metalminds.charge(item));h.assertTrue(!CopperBooks.get(p.server).books.containsKey(session.book),"Final zero still destroys all memories");CopperService.clear(p);h.succeed();
    }
    @GameTest(template="empty") public static void copperScreenshotCapacityCountsNormalizedBytesAndSavedMetadata(GameTestHelper h)throws Exception{
        var p=player(h);var item=mind(p);PowerData.state(p,"f:copper",-1);var session=CopperService.open(p,false);byte[] bytes=png(16,8);var transfer=UUID.randomUUID();request(p,BEGIN,transfer,"View","Saved pixels",bytes.length,new byte[0]);request(p,CHUNK,transfer,"","",0,bytes);request(p,FINISH,transfer,"","",0,new byte[0]);var page=pages(p).getFirst();
        h.assertTrue(page.imageBytes()==CopperImages.read(p.server,page.id()).length&&page.dataBytes()==CopperService.usedBytes(p,session),"Actual normalized server PNG bytes and page metadata share one budget");
        var loaded=CopperBooks.load(CopperBooks.get(p.server).save(new CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(loaded.books.get(session.book).get(page.id()).imageBytes()==page.imageBytes(),"Screenshot byte accounting survives a SavedData round trip");
        var legacy=page.save();legacy.remove("image_bytes");var oldPage=CopperPage.load(legacy);h.assertTrue(oldPage.imageBytes()==-1&&oldPage.dataBytes()>=page.dataBytes(),"Legacy screenshot metadata uses a conservative unknown-size allowance");CopperBooks.get(p.server).books.get(session.book).put(page.id(),oldPage);double beforeMigration=Metalminds.charge(item);CopperService.open(p,false);h.assertTrue(pages(p).getFirst().imageBytes()==page.imageBytes()&&Metalminds.charge(item)==beforeMigration,"Opening legacy screenshot metadata resolves server file size without granting charge");
        request(p,SAVE,page.id(),"Renamed","New description",0,new byte[0]);h.assertTrue(pages(p).getFirst().imageBytes()==page.imageBytes(),"Editing an image caption cannot erase its byte cost");
        request(p,DELETE,page.id(),"","",0,new byte[0]);CopperService.clear(p);
        var root=item.get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag();var tag=root.getCompound("cosmerearcanists_metalmind");tag.putDouble("capacity",1);tag.putDouble("charge",1);root.put("cosmerearcanists_metalmind",tag);item.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(root));CopperService.open(p,false);
        var noisy=new java.awt.image.BufferedImage(32,32,java.awt.image.BufferedImage.TYPE_INT_RGB);var random=new Random(123);for(int y=0;y<32;y++)for(int x=0;x<32;x++)noisy.setRGB(x,y,random.nextInt());var output=new ByteArrayOutputStream();ImageIO.write(noisy,"png",output);byte[] large=output.toByteArray();var rejected=UUID.randomUUID();long before;try(var files=java.nio.file.Files.list(CopperImages.directory(p.server))){before=files.count();}
        request(p,BEGIN,rejected,"Oversized memory","",large.length,new byte[0]);request(p,CHUNK,rejected,"","",0,large);request(p,FINISH,rejected,"","",0,new byte[0]);long after;try(var files=java.nio.file.Files.list(CopperImages.directory(p.server))){after=files.count();}
        h.assertTrue(pages(p).isEmpty()&&before==after&&Metalminds.charge(item)==1,"A screenshot beyond physical charge capacity leaves no page, orphan PNG or charge change");CopperService.clear(p);h.succeed();
    }

}
